// Fresh-process diagnostic only. No warm-TT reproduction or soak credit is claimed.
#include "uci_process.hpp"
#include "softnodes_labels.hpp"
#include "forge/search.hpp"
#include <fstream>
#include <iostream>
#include <memory>

namespace {
using Clock=std::chrono::steady_clock;
std::string quote(const std::string&s){std::string out="\"";const char*hex="0123456789abcdef";for(unsigned char c:s){if(c=='"'||c=='\\'){out+='\\';out+=char(c);}else if(c<32){out+="\\u00";out+=hex[c>>4];out+=hex[c&15];}else out+=char(c);}return out+'"';}
std::string line_file(const char*p){std::ifstream f(p);if(!f)throw std::runtime_error("input file unavailable");std::string s,extra;std::getline(f,s);if(s.empty()||std::getline(f,extra)||s.find('\r')!=std::string::npos)throw std::runtime_error("input must be one nonempty LF line");return s;}
forge::Board history_board(const std::string&position,const std::string&fen){forge::Board b;if(!b.set_fen(forge::Board::StandardStartFen))throw std::runtime_error("oracle start FEN");std::istringstream in(position);std::string token;for(const auto*expected:{"position","startpos","moves"}){if(!(in>>token)||token!=expected)throw std::runtime_error("expected exact startpos history");}while(in>>token){const auto moves=b.legal_moves();auto found=std::find_if(moves.begin(),moves.end(),[&](const auto&m){return forge::Board::move_to_uci(m)==token;});if(found==moves.end())throw std::runtime_error("illegal recorded history move: "+token);forge::Undo u;if(!b.make_move(*found,u))throw std::runtime_error("oracle history rejected");}if(b.fen()!=fen)throw std::runtime_error("history FEN mismatch: "+b.fen());return b;}
int remaining(Clock::time_point end){const auto n=std::chrono::duration_cast<std::chrono::milliseconds>(end-Clock::now()).count();if(n<=0)throw std::runtime_error("diagnostic deadline reached");return int(n);}
bool diagnostic(const std::string&s){for(const char*p:{"ThreadSanitizer","AddressSanitizer","UndefinedBehaviorSanitizer","LeakSanitizer","MemorySanitizer","runtime error:","Sanitizer CHECK failed","terminate called"})if(s.find(p)!=std::string::npos)return true;return false;}
struct Outcome{LabelCheck labels;bool legal=false,score_in_range=false,target_depth_complete=false;};
Outcome inspect(const std::vector<std::string>&lines,bool received,bool timed_out,const forge::Board&board,int target_depth=9,int threads=2){Outcome o;o.labels=check_labels(lines,false,threads);const auto legal=board.legal_moves();o.legal=std::any_of(legal.begin(),legal.end(),[&](const auto&m){return forge::Board::move_to_uci(m)==o.labels.bestmove;});o.score_in_range=o.labels.exact&&o.labels.score>=-forge::MateValue&&o.labels.score<=forge::MateValue;o.target_depth_complete=received&&!timed_out&&o.labels.error.empty()&&o.labels.exact&&o.labels.has_depth&&o.labels.depth==target_depth&&o.labels.has_nodes&&o.legal&&o.score_in_range;return o;}
std::string shutdown_json(const UciShutdownResult&s){return "{\"reaped\":"+std::to_string(s.reaped)+",\"exit\":"+std::to_string(s.exit_code)+",\"signal\":"+std::to_string(s.signal)+",\"timed_out\":"+std::to_string(s.timed_out)+",\"driver_sigterm\":"+std::to_string(s.driver_sigterm)+",\"driver_sigkill\":"+std::to_string(s.driver_sigkill)+",\"quit_attempted\":"+std::to_string(s.quit_attempted)+",\"quit_sent\":"+std::to_string(s.quit_sent)+",\"quit_to_exit_ms\":"+(s.quit_to_exit_ms<0?"null":std::to_string(s.quit_to_exit_ms))+",\"shutdown_budget_ms\":"+std::to_string(s.shutdown_budget_ms)+",\"shutdown_total_ms\":"+std::to_string(s.shutdown_total_ms)+",\"error\":"+quote(s.error)+"}";}
int self_test(char**argv){auto b=history_board(line_file(argv[2]),line_file(argv[3]));history_board(line_file(argv[4]),line_file(argv[5]));const auto move=forge::Board::move_to_uci(b.legal_moves().front());const std::vector<std::string> done={"info depth 9 score cp -10 nodes 123 time 4 pv "+move,"bestmove "+move};if(!inspect(done,true,false,b).target_depth_complete)throw std::runtime_error("synthetic depth9 completion");if(inspect(done,true,true,b).target_depth_complete)throw std::runtime_error("quit/timeout result credited");if(inspect({"info depth 8 score cp -10 nodes 123 time 4 pv "+move},false,true,b).target_depth_complete)throw std::runtime_error("missing bestmove credited");if(inspect({"info depth 9 score cp -10 lowerbound nodes 123 time 4 pv "+move,"bestmove "+move},true,false,b).target_depth_complete)throw std::runtime_error("bounded info credited");const std::vector<std::string> twelve={"info depth 12 score cp -10 nodes 456 time 7 pv "+move,"bestmove "+move};if(!inspect(twelve,true,false,b,12,1).target_depth_complete)throw std::runtime_error("target12 T1");if(!inspect(twelve,true,false,b,12,2).target_depth_complete)throw std::runtime_error("target12 T2");if(inspect(done,true,false,b,12,1).target_depth_complete)throw std::runtime_error("depth9 credited as12");if(inspect(twelve,true,false,b,9,2).target_depth_complete)throw std::runtime_error("depth12 credited as9");std::cout<<"SELFTEST two exact legal histories and eight completion cases passed; engine runs0\n";return 0;}
}
int main(int argc,char**argv){try{if(argc==6&&std::string(argv[1])=="--self-test")return self_test(argv);if(argc!=7)throw std::runtime_error("ENGINE POSITION_FILE FEN_FILE true|false THREADS DEPTH");const std::string engine_path=argv[1],position=line_file(argv[2]),fen=line_file(argv[3]),enabled=argv[4];if(enabled!="true"&&enabled!="false")throw std::runtime_error("invalid option boolean");const std::string thread_text=argv[5],depth_text=argv[6];if((thread_text!="1"&&thread_text!="2")||(depth_text!="9"&&depth_text!="12"))throw std::runtime_error("invalid threads/depth");const int threads=std::stoi(thread_text),target_depth=std::stoi(depth_text);const std::string go="go depth "+depth_text;const auto board=history_board(position,fen);const auto started=Clock::now(),setup_end=started+std::chrono::seconds(7);std::unique_ptr<UciProcess> engine;std::size_t published=0;std::vector<std::string> lines;bool received=false,timed_out=false,search_started=false,shutdown_observed=false;std::string error,startup_detail;double response_ms=0;UciShutdownResult shutdown;auto search_begin=started;
 auto event=[&](const char*name){std::cout<<"EVENT {\"event\":"<<quote(name)<<",\"elapsed_ms\":"<<std::chrono::duration<double,std::milli>(Clock::now()-started).count()<<"}"<<std::endl;};auto publish=[&](){if(engine){std::cout<<engine->transcript().substr(published);published=engine->transcript().size();std::cout.flush();}};
 std::cout<<"CONFIG {\"engine\":"<<quote(engine_path)<<",\"position\":"<<quote(position)<<",\"fen\":"<<quote(fen)<<",\"Threads\":"<<threads<<",\"Hash\":16,\"OwnBook\":false,\"UseNNUE\":true,\"MultiPV\":1,\"HindsightDepth\":"<<enabled<<",\"MateAlphaGuard\":"<<enabled<<",\"go\":"<<quote(go)<<",\"target_depth\":"<<target_depth<<",\"response_allowance_ms\":60000,\"shutdown_allowance_ms\":250,\"fresh_process\":true,\"warm_tt_reproduced\":false,\"soak_credit\":0}"<<std::endl;
 try{event("startup_begin");engine=std::make_unique<UciProcess>(engine_path,threads,remaining(setup_end));publish();for(const auto&command:{std::string("setoption name UseNNUE value true"),std::string("setoption name MultiPV value 1"),"setoption name HindsightDepth value "+enabled,"setoption name MateAlphaGuard value "+enabled,std::string("ucinewgame")})engine->send(command,remaining(setup_end));engine->ready(remaining(setup_end));engine->send(position,remaining(setup_end));publish();event("search_begin");search_begin=Clock::now();search_started=true;const auto response_end=search_begin+std::chrono::seconds(60);engine->send(go,remaining(response_end));publish();for(;;){const auto line=engine->line(remaining(response_end));lines.push_back(line);publish();event("received_line");if(line.rfind("bestmove",0)==0){received=true;break;}}response_ms=std::chrono::duration<double,std::milli>(Clock::now()-search_begin).count();event("bestmove_before_quit");}
 catch(const UciStartupError&e){startup_detail=e.what();error=startup_detail.substr(0,startup_detail.find('\n'));shutdown=e.shutdown;shutdown_observed=true;std::cout<<"STARTUP_ERROR "<<quote(startup_detail)<<std::endl;}
 catch(const std::exception&e){error=std::string(e.what()).substr(0,std::string(e.what()).find('\n'));timed_out=search_started&&!received&&(error=="engine response timeout"||error=="diagnostic deadline reached");if(search_started)response_ms=std::chrono::duration<double,std::milli>(Clock::now()-search_begin).count();publish();event("response_error_before_quit");}
 const auto outcome=inspect(lines,received,timed_out,board,target_depth,threads);event("pre_quit_snapshot_frozen");if(engine){event("quit_begin");shutdown=engine->finish(250);shutdown_observed=true;publish();event("quit_end");}const bool reports=engine?diagnostic(engine->transcript()):diagnostic(startup_detail+shutdown.transcript);const bool normal=shutdown_observed&&shutdown.reaped&&shutdown.exit_code==0&&shutdown.signal==0&&!shutdown.timed_out&&!shutdown.driver_sigterm&&!shutdown.driver_sigkill&&shutdown.error.empty();const bool success=outcome.target_depth_complete&&normal&&!reports&&error.empty();
 std::cout<<"RESULT {\"search_started\":"<<search_started<<",\"bestmove_received_before_quit\":"<<received<<",\"response_timed_out\":"<<timed_out<<",\"response_ms\":"<<response_ms<<",\"target_depth_completed_before_quit\":"<<outcome.target_depth_complete<<",\"bestmove\":"<<quote(outcome.labels.bestmove)<<",\"last_exact\":"<<quote(outcome.labels.exact_line)<<",\"score_kind\":"<<quote(outcome.labels.kind)<<",\"score\":"<<outcome.labels.score<<",\"depth\":"<<outcome.labels.depth<<",\"nodes\":"<<outcome.labels.nodes<<",\"target_depth\":"<<target_depth<<",\"threads\":"<<threads<<",\"legal_returned_move\":"<<outcome.legal<<",\"score_in_range\":"<<outcome.score_in_range<<",\"parser_error\":"<<quote(outcome.labels.error)<<",\"error\":"<<quote(error)<<",\"sanitizer_report_observed\":"<<reports<<",\"normal_exit\":"<<normal<<",\"shutdown\":"<<shutdown_json(shutdown)<<",\"diagnostic_success\":"<<success<<",\"soak_credit\":0,\"warm_tt_reproduced\":false}"<<std::endl;return success?0:1;
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
